import { AppError } from '@aic/ipc';
import type Database from 'better-sqlite3';
import journal from '../drizzle/meta/_journal.json';

/**
 * SQL migrations generated by drizzle-kit, embedded at build time so the packaged
 * app needs no migration files on disk. The schema version is `PRAGMA user_version`.
 */
export interface Migration {
  version: number;
  tag: string;
  statements: string[];
}

const sqlFiles = import.meta.glob<string>('../drizzle/*.sql', {
  query: '?raw',
  import: 'default',
  eager: true,
});

export const MIGRATIONS: Migration[] = [...journal.entries]
  .sort((a, b) => a.idx - b.idx)
  .map((entry, index) => {
    const sql = sqlFiles[`../drizzle/${entry.tag}.sql`];
    if (sql === undefined) throw new Error(`Missing migration file for ${entry.tag}`);
    return {
      version: index + 1,
      tag: entry.tag,
      statements: sql
        .split('--> statement-breakpoint')
        .map((s) => s.trim())
        .filter(Boolean),
    };
  });

export function schemaVersion(sqlite: Database.Database): number {
  return sqlite.pragma('user_version', { simple: true }) as number;
}

/** Applies pending migrations, each in its own transaction. Returns the new version. */
export function runMigrations(
  sqlite: Database.Database,
  migrations: readonly Migration[] = MIGRATIONS,
): number {
  const from = schemaVersion(sqlite);
  const latest = migrations.length;
  if (from > latest) {
    throw new AppError(
      'db_newer_than_app',
      `Your data was saved by a newer version of the app (schema ${from}; this version supports ${latest}). Update the app to open it.`,
    );
  }
  for (const migration of migrations.slice(from)) {
    sqlite.transaction(() => {
      for (const statement of migration.statements) sqlite.exec(statement);
      sqlite.pragma(`user_version = ${migration.version}`);
    })();
  }
  return schemaVersion(sqlite);
}
